## Source &mdash; `tests/core/test_convert_bench.cpp`

```cpp
/**************************************************************************/
/*  test_convert_bench.cpp                                                */
/**************************************************************************/

#include "tests/test_macros.h"

TEST_FORCE_LINK(test_convert_bench)

#include "core/variant/array.h"
#include "core/variant/container_type_validate.h"
#include "core/variant/dictionary.h"
#include "core/variant/variant.h"

#include <algorithm>
#include <chrono>

namespace TestConvertBench {

static uint64_t sink = 0;

static ContainerType ct(Variant::Type p_type) {
	ContainerType t;
	t.variant_type = p_type;
	return t;
}

static Array typed_float_array() {
	Array a;
	a.set_typed(ct(Variant::FLOAT));
	return a;
}

static Dictionary typed_float_dict() {
	Dictionary d;
	d.set_typed(ct(Variant::FLOAT), ct(Variant::FLOAT));
	return d;
}

using Clock = std::chrono::steady_clock;

static double elapsed_us(Clock::time_point p_begin, Clock::time_point p_end) {
	return std::chrono::duration<double, std::micro>(p_end - p_begin).count();
}

static double median(LocalVector<double> &p_samples) {
	std::sort(p_samples.ptr(), p_samples.ptr() + p_samples.size());
	return p_samples[p_samples.size() / 2];
}

// Each bench times one sample of `p_n` operations, `p_reps` times, and returns the median in microseconds.
// `p_values` holds the inputs: ints (converting to float) or floats (control, no conversion).

static double bench_push_back(const Array &p_values, int p_reps) {
	LocalVector<double> samples;
	const int n = p_values.size();
	for (int r = 0; r < p_reps; r++) {
		Array target = typed_float_array();
		const auto begin = Clock::now();
		for (int i = 0; i < n; i++) {
			target.push_back(p_values[i]);
		}
		samples.push_back(elapsed_us(begin, Clock::now()));
		sink += target.size();
	}
	return median(samples);
}

static double bench_set(const Array &p_values, int p_reps) {
	LocalVector<double> samples;
	const int n = p_values.size();
	for (int r = 0; r < p_reps; r++) {
		Array target = typed_float_array();
		target.resize(n);
		const auto begin = Clock::now();
		for (int i = 0; i < n; i++) {
			target.set(i, p_values[i]);
		}
		samples.push_back(elapsed_us(begin, Clock::now()));
		sink += target.size();
	}
	return median(samples);
}

static double bench_append_array(const Array &p_values, int p_reps) {
	LocalVector<double> samples;
	for (int r = 0; r < p_reps; r++) {
		Array target = typed_float_array();
		const auto begin = Clock::now();
		target.append_array(p_values);
		samples.push_back(elapsed_us(begin, Clock::now()));
		sink += target.size();
	}
	return median(samples);
}

static double bench_dict_set(const Array &p_values, int p_reps) {
	LocalVector<double> samples;
	const int n = p_values.size();
	for (int r = 0; r < p_reps; r++) {
		Dictionary target = typed_float_dict();
		const auto begin = Clock::now();
		for (int i = 0; i < n; i++) {
			target.set(p_values[i], p_values[i]);
		}
		samples.push_back(elapsed_us(begin, Clock::now()));
		sink += target.size();
	}
	return median(samples);
}

static double bench_dict_merge(const Dictionary &p_source, int p_reps) {
	LocalVector<double> samples;
	for (int r = 0; r < p_reps; r++) {
		Dictionary target = typed_float_dict();
		const auto begin = Clock::now();
		target.merge(p_source);
		samples.push_back(elapsed_us(begin, Clock::now()));
		sink += target.size();
	}
	return median(samples);
}

static int convert_bench() {
	const int sizes[] = { 1000, 10000, 100000 };

	print_line("scenario,n,median_us");

	for (int s = 0; s < 3; s++) {
		const int n = sizes[s];
		const int reps = MAX(5, 2000000 / n);

		Array ints;
		Array floats;
		Dictionary int_dict;
		Dictionary float_dict;
		for (int i = 0; i < n; i++) {
			ints.push_back(i);
			floats.push_back(double(i));
			int_dict[i] = i;
			float_dict[double(i)] = double(i);
		}

		print_line(vformat("A_push_back_convert,%d,%f", n, bench_push_back(ints, reps)));
		print_line(vformat("A_push_back_control,%d,%f", n, bench_push_back(floats, reps)));
		print_line(vformat("B_set_convert,%d,%f", n, bench_set(ints, reps)));
		print_line(vformat("B_set_control,%d,%f", n, bench_set(floats, reps)));
		print_line(vformat("C_append_array_convert,%d,%f", n, bench_append_array(ints, reps)));
		print_line(vformat("C_append_array_control,%d,%f", n, bench_append_array(floats, reps)));
		print_line(vformat("D_dict_set_convert,%d,%f", n, bench_dict_set(ints, reps)));
		print_line(vformat("D_dict_set_control,%d,%f", n, bench_dict_set(floats, reps)));
		print_line(vformat("E_dict_merge_convert,%d,%f", n, bench_dict_merge(int_dict, reps)));
		print_line(vformat("E_dict_merge_control,%d,%f", n, bench_dict_merge(float_dict, reps)));
	}

	print_line(vformat("sink,%d,0", sink));
	return 0;
}

REGISTER_TEST_COMMAND("convert-bench", &convert_bench)

} // namespace TestConvertBench
```

