```gdscript
extends SceneTree

# Method calls (set, push_back, ...) take Variant parameters, so GDScript passes ints through unconverted
# and the conversion happens inside the container.

func median(samples: Array[float]) -> float:
	samples.sort()
	return samples[samples.size() / 2]

func bench_push_back(values: Array, reps: int) -> float:
	var s: Array[float] = []
	for r in reps:
		var target: Array[float] = []
		var t0 := Time.get_ticks_usec()
		for v in values:
			target.push_back(v)
		s.append(Time.get_ticks_usec() - t0)
	return median(s)

func bench_set(values: Array, reps: int) -> float:
	var s: Array[float] = []
	var n := values.size()
	for r in reps:
		var target: Array[float] = []
		target.resize(n)
		var t0 := Time.get_ticks_usec()
		for i in n:
			target.set(i, values[i])
		s.append(Time.get_ticks_usec() - t0)
	return median(s)

func bench_append_array(values: Array, reps: int) -> float:
	var s: Array[float] = []
	for r in reps:
		var target: Array[float] = []
		var t0 := Time.get_ticks_usec()
		target.append_array(values)
		s.append(Time.get_ticks_usec() - t0)
	return median(s)

func bench_dict_set(values: Array, reps: int) -> float:
	var s: Array[float] = []
	for r in reps:
		var target: Dictionary[float, float] = {}
		var t0 := Time.get_ticks_usec()
		for v in values:
			target.set(v, v)
		s.append(Time.get_ticks_usec() - t0)
	return median(s)

func bench_dict_merge(source: Dictionary, reps: int) -> float:
	var s: Array[float] = []
	for r in reps:
		var target: Dictionary[float, float] = {}
		var t0 := Time.get_ticks_usec()
		target.merge(source)
		s.append(Time.get_ticks_usec() - t0)
	return median(s)

func _init() -> void:
	print("scenario,n,median_us")
	for n in [1000, 10000, 100000]:
		var reps: int = maxi(5, 2000000 / n)

		var ints := []
		var floats := []
		var int_dict := {}
		var float_dict := {}
		for i in n:
			ints.append(i)
			floats.append(float(i))
			int_dict[i] = i
			float_dict[float(i)] = float(i)

		print("A_push_back_convert,%d,%f" % [n, bench_push_back(ints, reps)])
		print("A_push_back_control,%d,%f" % [n, bench_push_back(floats, reps)])
		print("B_set_convert,%d,%f" % [n, bench_set(ints, reps)])
		print("B_set_control,%d,%f" % [n, bench_set(floats, reps)])
		print("C_append_array_convert,%d,%f" % [n, bench_append_array(ints, reps)])
		print("C_append_array_control,%d,%f" % [n, bench_append_array(floats, reps)])
		print("D_dict_set_convert,%d,%f" % [n, bench_dict_set(ints, reps)])
		print("D_dict_set_control,%d,%f" % [n, bench_dict_set(floats, reps)])
		print("E_dict_merge_convert,%d,%f" % [n, bench_dict_merge(int_dict, reps)])
		print("E_dict_merge_control,%d,%f" % [n, bench_dict_merge(float_dict, reps)])

	quit()
